let shotT=-999,warnCd=0,curT='',slowT=0,mulT=0,ch=[],left=0,lv=1,score=0,combo=0,groups=0,st='menu',freeze=0,pj=null,cur=0,nxt=0,ang=0,fx=[],tx=[],qp=false,curA=0,prevC=-1;
const nc=()=>Math.min(6,3+((lv-1)>>1)),rnd=(a,b)=>a+(Math.random()*(b-a+1)|0);
function spawnC(){let c=(prevC>=0&&Math.random()<.4)?prevC:rnd(0,nc()-1);prevC=c;return c}
function shotC(){if(ch.length&&Math.random()<.85){return ch[rnd(0,ch.length-1)].c}return rnd(0,nc()-1)}
