const ov=document.getElementById('ov');
function show(h){ov.innerHTML=h;ov.style.display='flex'}function hide(){ov.style.display='none'}
function menu(){show(`<img src="data:image/png;base64," alt="Cyclo" style="height:92px"><h1>🐸 Rana Matemática</h1><div style="font-size:20px">Creador: <b style="color:#ffd35c">cyclo45</b></div><div class="ins"><p>🎯 <b>Apunta</b> con el mouse y <b>haz clic</b> para disparar.</p><p>💥 Junta <b>3 o más bolas del mismo color</b>.</p><p>🧠 Cada 3 grupos sale un <b>reto mental de 15 segundos</b>: si aciertas, ganas un <b>poder</b> ❄️ ⏪ 💣 ⚡ 🐢 ✖️3</p><p>🔁 <b>Espacio</b> o clic derecho = cambiar bola <small>(en el celular, toca la rana)</small></p><p>🏆 Pasa los <b>3 niveles</b> y abre la <b>caja sorpresa</b> 🎁</p></div><button class="btn" onclick="start()">Jugar</button>`)}
// ---- retos matemáticos
let qIv=0;
function quiz(){st='quiz';const co=()=>Math.random()<.5;let q,a;const t=rnd(0,2);
if(t==0){const x=rnd(20,60+lv*15),y=rnd(15,50+lv*10);q=`${x} + ${y}`;a=x+y}
else if(t==1){const x=rnd(40,100+lv*20),y=rnd(15,Math.min(45,x-10));q=`${x} − ${y}`;a=x-y}
else{const y=rnd(3,9),z=rnd(4,12+lv*2);q=`${y*z} ÷ ${y}`;a=z}
q+=' = ?';const ops=[a];while(ops.length<3){const d=a+(co()?1:-1)*rnd(1,Math.max(3,a/6|0));if(d>0&&!ops.includes(d))ops.push(d)}
ops.sort(()=>Math.random()-.5);curA=ops.indexOf(a);curT=String(a);
show(`<h2>🧠 ¡Reto mental!</h2><div style="font-size:36px;font-weight:bold">${q}</div><div>${ops.map((v,i)=>`<button class="btn" onclick="ansQ(${i})">${v}</button>`).join('')}</div><div style="width:min(80%,360px);height:10px;background:#143;border-radius:6px;overflow:hidden"><div id="qb" style="height:100%;width:100%;background:#ffd35c"></div></div><div>⏱ <b id="qn">15</b> s</div><small>Acierta para ganar un poder</small>`);
const t0=performance.now();clearInterval(qIv);qIv=setInterval(()=>{const r=15-(performance.now()-t0)/1000;if(r<=0){ansQ(-1);return}document.getElementById('qb').style.width=r/15*100+'%';document.getElementById('qn').textContent=Math.ceil(r)},100)}
function ansQ(v){clearInterval(qIv);if(v===curA){score+=150*lv;const r=rnd(0,5);
if(r==0){freeze=360;play('slow');pop('¡Correcto! ❄️ Congelado 6s')}
else if(r==1){ch.forEach(b=>b.d=Math.max(0,b.d-260));pop('¡Correcto! ⏪ Retroceden')}
else if(r==2){const k=Math.min(7,ch.length);for(let j=0;j<k;j++)for(let q=0;q<5;q++){const t=Math.random()*6.28;fx.push({x:ch[j].x,y:ch[j].y,vx:Math.cos(t)*3,vy:Math.sin(t)*3,c:'#ffa63f',l:30})}play('bomb',.6);ch.splice(0,k);score+=k*20;pop('¡Correcto! 💣 Bomba ×'+k)}
else if(r==3){let pr=false,n=0;const o=[];ch.forEach(b=>{if(b.c===cur){pr=true;n++;fx.push({x:b.x,y:b.y,vx:2,vy:-2,c:COL[b.c],l:30})}else{if(pr)b.g=true;pr=false;o.push(b)}});ch=o;if(n)play('bomb',.6);score+=n*15;pop('¡Correcto! ⚡ Rayo: '+n+' bolas')}
else if(r==4){slowT=900;play('slow');pop('¡Correcto! 🐢 Cámara lenta 15s')}
else{mulT=900;pop('¡Correcto! ✖️3 Puntos triples 15s')}}else{combo=0;ch.forEach(b=>b.d+=40);pop((v<0?'⏱ Era ':'Era ')+curT)}hide();st='play'}
function pop(s,x=CX,y=CY-70){tx.push({x,y,s,l:90})}
// ---- coincidencias
function match(i,cb){const c=ch[i].c;let a=i,b=i;while(a>0&&ch[a-1].c===c)a--;while(b<ch.length-1&&ch[b+1].c===c)b++;const n=b-a+1;if(n<3)return false;
const gain=n*10*cb*(mulT>0?3:1),m=ch[(a+b)>>1];
for(let k=a;k<=b;k++)for(let j=0;j<6;j++){const t=Math.random()*6.28,s=1+Math.random()*3;fx.push({x:ch[k].x,y:ch[k].y,vx:Math.cos(t)*s,vy:Math.sin(t)*s,c:COL[c],l:30})}
play('d'+rnd(1,5),.28,1+Math.min(cb,6)*.04);ch.splice(a,n);if(a<ch.length&&a>0)ch[a].g=true;
score+=gain;combo=cb;pop(`+${gain}  (${n}×10×${cb}${mulT>0?'×3':''})`,m.x,m.y);groups++;if(groups%3===0)qp=true;return true}
function shoot(){if(st!=='play'||pj)return;shotT=performance.now();play('click1');const c=Math.cos(ang),s=Math.sin(ang);pj={x:CX+c*(MD+10),y:CY+s*(MD+10),vx:c*13,vy:s*13,c:cur};cur=nxt;nxt=shotC()}
function swap(){if(st==='play'){[cur,nxt]=[nxt,cur]}}
function insert(j){const b=ch[j],p1=pos(b.d+6),p0=pos(b.d-6),dot=(p1[0]-p0[0])*(pj.x-b.x)+(p1[1]-p0[1])*(pj.y-b.y),front=dot>0;
const idx=front?j:j+1,nb=mk(pj.c,front?b.d:b.d-GAP);nb.x=pj.x;nb.y=pj.y;ch.splice(idx,0,nb);
for(let i=idx;i>=0&&i+1<ch.length;i--)if(ch[i].d<ch[i+1].d+GAP)ch[i].d=ch[i+1].d+GAP;
pj=null;play('click2');if(!match(idx,combo+1))combo=0}
const SND={"click1": "", "click2": "", "bomb": "", "slow": "", "warn": "", "d1": "", "d2": "", "d3": "", "d4": "", "d5": ""};let AC=null;const BUF={};
function initAudio(){if(AC){if(AC.state==='suspended')AC.resume();return}try{AC=new(window.AudioContext||window.webkitAudioContext)();for(const k in SND){const b=atob(SND[k]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);AC.decodeAudioData(u.buffer).then(x=>BUF[k]=x).catch(()=>{})}}catch(e){}}
function play(k,vol=.7,rate=1){if(!AC||!BUF[k])return;if(AC.state==='suspended')AC.resume();const s=AC.createBufferSource(),gn=AC.createGain();s.buffer=BUF[k];s.playbackRate.value=rate;gn.gain.value=vol;s.connect(gn).connect(AC.destination);s.start()}
const MUS=["", "", ""];let mus=null,musI=-1;const MV=.5;
function b2u(b64){const b=atob(b64),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u}
function stopMusic(){musI=-1;if(mus){try{mus.stop?mus.stop():mus.pause()}catch(e){}mus=null}}
function fbMusic(i){if(musI!==i||!AC)return;try{AC.decodeAudioData(b2u(MUS[i]).buffer).then(buf=>{if(musI!==i)return;const so=AC.createBufferSource(),gn=AC.createGain();so.buffer=buf;so.loop=true;gn.gain.value=MV;so.connect(gn).connect(AC.destination);so.start();mus=so})}catch(e){}}
function playMusic(i){stopMusic();musI=i;try{const a=new Audio(URL.createObjectURL(new Blob([b2u(MUS[i])],{type:'audio/mpeg'})));a.loop=true;a.volume=MV;a.onerror=()=>fbMusic(i);mus=a;const p=a.play();if(p&&p.catch)p.catch(()=>fbMusic(i))}catch(e){fbMusic(i)}}
// ---- lógica
function step(){
if(st!=='play')return;
const v=freeze>0?0:(left>0?2.6:(.4+lv*.06)*(slowT>0?.35:1));if(freeze>0)freeze--;if(slowT>0)slowT--;if(mulT>0)mulT--;
if(left>0&&(!ch.length||ch[ch.length-1].d>=GAP)){ch.push(mk(spawnC(),ch.length?ch[ch.length-1].d-GAP:0));left--}
let cat=false,pend=-1;
for(let i=0;i<ch.length;i++){const b=ch[i];if(!i){b.d+=v;continue}const p=ch[i-1];if(b.g)cat=true;b.d+=v+(cat?7:0);const lim=p.d-GAP;
if(b.d>=lim){b.d=lim;if(b.g){b.g=false;if(b.c===p.c&&pend<0)pend=i}}}
if(pend>=0&&!match(pend,combo+1))combo=0;
if(pj){pj.x+=pj.vx;pj.y+=pj.vy;if(pj.x<-30||pj.x>W+30||pj.y<-30||pj.y>H+30)pj=null;else{let h=-1,bd=26;ch.forEach((b,i)=>{const d=Math.hypot(b.x-pj.x,b.y-pj.y);if(d<bd){bd=d;h=i}});if(h>=0)insert(h)}}
ch.forEach(b=>{const p=pos(b.d);b.x+=(p[0]-b.x)*.4;b.y+=(p[1]-b.y)*.4});
fx.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.l--});fx=fx.filter(p=>p.l>0);tx.forEach(t=>{t.y-=.6;t.l--});tx=tx.filter(t=>t.l>0);
if(ch.length&&ch[0].d>L*.88&&freeze<=0){if(warnCd<=0){play('warn',.6);warnCd=100}}warnCd--;if(ch.length&&ch[0].d>=L-20){st='over';stopMusic();show(`<h1>💀 ¡Te la tragaron!</h1><div style="font-size:24px">Puntos: <b>${score}</b> · Nivel ${lv}</div><button class="btn" onclick="start()">Reintentar</button>`);return}
if(!left&&!ch.length&&!pj){st='won';if(lv>=3){finale();return}show(`<h1>🎉 ¡Nivel ${lv} superado!</h1><div style="font-size:24px">Puntos: <b>${score}</b></div><small>Siguiente nivel: más bolas, más velocidad y retos más difíciles.</small><button class="btn" onclick="next()">Siguiente nivel</button>`);return}
if(qp){qp=false;quiz()}}
const RAR=[{n:'Nada',e:'💨',q:'Mala suerte',col:'#6b7a86',w:6},{n:'1 dulce',e:'🍬',q:'Rara',col:'#9b5bff',w:79},{n:'2 décimas',e:'📝',q:'Legendaria',col:'#ffd35c',w:15}];
function pick(){let t=Math.random()*100;for(const r of RAR)if((t-=r.w)<0)return r;return RAR[0]}
function finale(){show(`<h1>🏆 ¡Completaste el nivel 3!</h1><div style="font-size:24px">Puntos: <b>${score}</b></div><small>Te ganaste una caja sorpresa: puede tener 1 dulce, 2 décimas para tu nota o nada. ¡Ábrela!</small><button class="btn" onclick="openCase()">🎁 Abrir caja</button>`)}
function openCase(){const win=pick(),WI=34,items=[];for(let i=0;i<56;i++)items.push(i==WI?win:pick());
show(`<h2>🎁 Caja de Dulces</h2><div id="cs" style="position:relative;width:min(94%,640px);height:130px;overflow:hidden;border:3px solid #ffd35c;border-radius:10px;background:#0a120e"><div id="tr" style="display:flex;height:100%;will-change:transform">${items.map(r=>`<div style="flex:none;width:110px;height:100%;box-sizing:border-box;border-bottom:5px solid ${r.col};background:linear-gradient(#16231c,${r.col}66);display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:30px">${r.e}<span style="font-size:12px">${r.n}</span></div>`).join('')}</div><div style="position:absolute;left:50%;top:0;bottom:0;width:3px;margin-left:-1px;background:#ffd35c;box-shadow:0 0 10px #ffd35c"></div></div><div id="rs" style="font-size:24px;min-height:90px"></div>`);
const cs=document.getElementById('cs'),tr=document.getElementById('tr'),tg=WI*110+55+(Math.random()*70-35)-cs.offsetWidth/2,t0=performance.now();
(function f(t){const k=Math.min(1,(t-t0)/6000),e=1-Math.pow(1-k,4);tr.style.transform=`translateX(${-tg*e}px)`;if(k<1)requestAnimationFrame(f);else document.getElementById('rs').innerHTML=`<b style="color:${win.col}">${win.e} ${win.n}</b> <small>(${win.q})</small><br><button class="btn" onclick="start()">Jugar otra vez</button>`})(t0)}
// ---- dibujo
function ball(x,y,c,r=R){const z=r*2.4;g.drawImage(SP[c],x-z/2,y-z/2,z,z)}
function draw(){g.drawImage(bgW,0,0);const TT=performance.now()/1000;g.lineWidth=1.5;RP.forEach(o=>{const k=((TT*.35+o.p)%6.28)/6.28,rd=8+k*40;g.strokeStyle='rgba(190,240,225,'+(.28*(1-k))+')';g.beginPath();g.ellipse(o.x,o.y,rd*1.6,rd*.55,0,0,7);g.stroke()});g.drawImage(bgP,0,0);
for(let i=0;i<16;i++){const x=(i*173.7+Math.sin(TT*.4+i)*40)%W,y=(i*97.3%H)+Math.cos(TT*.5+i*2)*30,al=.5+.5*Math.sin(TT*2+i*3),gr=g.createRadialGradient(x,y,0,x,y,12);gr.addColorStop(0,'rgba(255,240,140,'+al*.9+')');gr.addColorStop(1,'rgba(255,240,140,0)');g.fillStyle=gr;g.fillRect(x-12,y-12,24,24)}

ch.forEach(b=>ball(b.x,b.y,b.c));if(pj)ball(pj.x,pj.y,pj.c);
if(st==='play'){g.setLineDash([4,9]);g.strokeStyle='rgba(255,255,255,.28)';g.lineWidth=2;g.beginPath();g.moveTo(CX+Math.cos(ang)*60,CY+Math.sin(ang)*60);g.lineTo(CX+Math.cos(ang)*300,CY+Math.sin(ang)*300);g.stroke();g.setLineDash([])}
const c=Math.cos(ang),s=Math.sin(ang);
const ext=Math.max(0,1-(performance.now()-shotT)/170);
g.save();g.translate(CX,CY);g.rotate(ang-Math.PI/2);g.drawImage(FR,-DF/2,-DF/2,DF,DF);
if(ext>0){const e=Math.sin(ext*Math.PI);g.drawImage(TG,-TW/2,MD-6,TW,12+TL*1.6*e)}
g.restore();
ball(CX-c*HD,CY-s*HD,nxt,9);if(ext<=0)ball(CX+c*(MD+5),CY+s*(MD+5),cur);
fx.forEach(p=>{g.globalAlpha=p.l/30;g.fillStyle=p.c;g.fillRect(p.x-2,p.y-2,5,5)});g.globalAlpha=1;
g.font='bold 20px Georgia';g.textAlign='center';tx.forEach(t=>{g.globalAlpha=Math.min(1,t.l/30);g.fillStyle='#000';g.fillText(t.s,t.x+1,t.y+1);g.fillStyle='#ffd35c';g.fillText(t.s,t.x,t.y)});g.globalAlpha=1;
if(freeze>0){g.fillStyle='rgba(120,200,255,.14)';g.fillRect(0,0,W,H)}
document.getElementById('s').textContent=score;document.getElementById('l').textContent=lv;document.getElementById('c').textContent='x'+combo;document.getElementById('f').textContent=[freeze>0?'❄️ '+Math.ceil(freeze/60)+'s':'',slowT>0?'🐢':'',mulT>0?'✖️3':''].join(' ')}
let last=0,ac=0;function loop(t){ac+=Math.min(100,t-last);last=t;while(ac>=16.67){step();ac-=16.67}draw();requestAnimationFrame(loop)}
// ---- entrada
function mp(e){const r=cv.getBoundingClientRect();return[(e.clientX-r.left)*W/r.width,(e.clientY-r.top)*H/r.height]}
cv.addEventListener('pointermove',e=>{const[x,y]=mp(e);ang=Math.atan2(y-CY,x-CX)});
cv.addEventListener('pointerdown',e=>{const[x,y]=mp(e);ang=Math.atan2(y-CY,x-CX);if(e.button===2||Math.hypot(x-CX,y-CY)<30)swap();else shoot()});
cv.addEventListener('contextmenu',e=>e.preventDefault());
addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();swap()}});
function fit(){const h=document.getElementById('hud').offsetHeight+8;document.getElementById('wrap').style.width=Math.max(300,Math.min(innerWidth,(innerHeight-h)*W/H))+'px'}addEventListener('resize',fit);fit();
let dnT=0;addEventListener('pointerdown',()=>{clearTimeout(dnT);document.documentElement.classList.add('dn')});['pointerup','pointercancel'].forEach(e=>addEventListener(e,()=>{clearTimeout(dnT);dnT=setTimeout(()=>document.documentElement.classList.remove('dn'),220)}));
menu();requestAnimationFrame(t=>{last=t;loop(t)});
